import { Source } from './source';
import { mapEvent } from './mapper';
export class EventService {
  constructor(private readonly source: Source, private readonly mapper: (value: string) => string = mapEvent) {}
  async *stream(): AsyncGenerator<string> {
    // Generator bodies run lazily: the lease is opened on the first next() call,
    // and returning an unstarted generator never reaches this point.
    const lease = await this.source.open();
    let failure = false;
    try {
      for (;;) {
        const value = await lease.read();
        if (value === null) break;
        yield this.mapper(value);
      }
    } catch (error) {
      // Read, mapper or consumer-injected (throw()) failure: remember it so a
      // close failure cannot mask the original exception.
      failure = true;
      throw error;
    } finally {
      if (failure) {
        try { await lease.close(); } catch { /* preserve original error */ }
      } else {
        // Normal exhaustion or consumer break/return: close failure propagates.
        await lease.close();
      }
    }
  }
}
