const assert = require('node:assert/strict');
const { EventService } = require('../.build/service');

function makeSource(values, opts = {}) {
  const log = { opens: 0, reads: 0, closes: 0 };
  const source = {
    open: async () => {
      log.opens++;
      return {
        read: async () => {
          log.reads++;
          if (opts.readFailAt === log.reads) throw new Error('read failed');
          const v = values.shift();
          return v === undefined ? null : v;
        },
        close: async () => { log.closes++; if (opts.closeFails) throw new Error('close failed'); },
      };
    },
  };
  return { source, log };
}

async function main() {
  // Normal exhaustion, ordering.
  {
    const { source, log } = makeSource(['a', 'b', null]);
    const found = []; for await (const v of new EventService(source).stream()) found.push(v);
    assert.deepEqual(found, ['A', 'B']); assert.deepEqual(log, { opens: 1, reads: 3, closes: 1 });
  }
  // Lazy open, no read-ahead.
  {
    const { source, log } = makeSource(['a', 'b', 'c', null]);
    const gen = new EventService(source).stream();
    assert.equal(log.opens, 0);
    assert.deepEqual(await gen.next(), { value: 'A', done: false });
    assert.deepEqual(log, { opens: 1, reads: 1, closes: 0 });
    await gen.next();
    assert.equal(log.reads, 2);
    await gen.return(undefined);
    assert.deepEqual(log, { opens: 1, reads: 2, closes: 1 });
  }
  // Return of unopened generator.
  {
    const { source, log } = makeSource(['a', null]);
    const gen = new EventService(source).stream();
    assert.deepEqual(await gen.return(undefined), { value: undefined, done: true });
    assert.deepEqual(log, { opens: 0, reads: 0, closes: 0 });
  }
  // Consumer break.
  {
    const { source, log } = makeSource(['a', 'b', null]);
    for await (const v of new EventService(source).stream()) { assert.equal(v, 'A'); break; }
    assert.deepEqual(log, { opens: 1, reads: 1, closes: 1 });
  }
  // Break with close failure propagates close failure.
  {
    const { source, log } = makeSource(['a', null], { closeFails: true });
    await assert.rejects(async () => { for await (const _ of new EventService(source).stream()) break; }, /close failed/);
    assert.equal(log.closes, 1);
  }
  // Exhaustion with close failure propagates close failure.
  {
    const { source, log } = makeSource([null], { closeFails: true });
    await assert.rejects(async () => { for await (const _ of new EventService(source).stream()); }, /close failed/);
    assert.equal(log.closes, 1);
  }
  // Read failure, with and without close failure.
  for (const closeFails of [false, true]) {
    const { source, log } = makeSource(['a', 'b', null], { readFailAt: 2, closeFails });
    const found = [];
    await assert.rejects(async () => { for await (const v of new EventService(source).stream()) found.push(v); }, /read failed/);
    assert.deepEqual(found, ['A']); assert.equal(log.closes, 1);
  }
  // Mapper failure, with and without close failure.
  for (const closeFails of [false, true]) {
    const { source, log } = makeSource(['a', 'b', null], { closeFails });
    const svc = new EventService(source, (v) => { if (v === 'b') throw new Error('mapper failed'); return v; });
    await assert.rejects(async () => { for await (const _ of svc.stream()); }, /mapper failed/);
    assert.deepEqual(log, { opens: 1, reads: 2, closes: 1 });
  }
  // Consumer-injected throw, with and without close failure.
  for (const closeFails of [false, true]) {
    const { source, log } = makeSource(['a', 'b', null], { closeFails });
    const gen = new EventService(source).stream();
    await gen.next();
    await assert.rejects(gen.throw(new Error('injected')), /injected/);
    assert.deepEqual(log, { opens: 1, reads: 1, closes: 1 });
    assert.deepEqual(await gen.next(), { value: undefined, done: true });
    assert.equal(log.closes, 1);
  }
  // Throw into unopened generator opens nothing.
  {
    const { source, log } = makeSource(['a', null]);
    await assert.rejects(new EventService(source).stream().throw(new Error('x')), /x/);
    assert.deepEqual(log, { opens: 0, reads: 0, closes: 0 });
  }
}
module.exports = main();
EOF
